#!/usr/bin/env bun

/**
 * JSON validator script that reads from stdin and validates JSON input.
 * Exit codes: 0 for valid JSON, 1 for invalid JSON or errors.
 */

async function validateJson(): Promise<void> {
  try {
    const stdin = Bun.stdin;
    const reader = stdin.stream().getReader();
    const chunks: Uint8Array[] = [];

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
    }

    const totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);
    const combined = new Uint8Array(totalLength);
    let offset = 0;
    for (const chunk of chunks) {
      combined.set(chunk, offset);
      offset += chunk.length;
    }

    const input = new TextDecoder().decode(combined).trim();

    if (input.length === 0) {
      console.error("Error: Empty input");
      process.exit(1);
    }

    JSON.parse(input);
    console.log("Valid JSON");
    process.exit(0);
  } catch (error) {
    if (error instanceof SyntaxError) {
      console.error(`Error: Invalid JSON - ${error.message}`);
    } else {
      console.error(`Error: ${error instanceof Error ? error.message : String(error)}`);
    }
    process.exit(1);
  }
}

validateJson();

import { describe, expect, test } from "bun:test";
import { spawn } from "bun";

describe("validate-json", () => {
  test("accepts valid JSON object", async () => {
    const proc = spawn({
      cmd: ["bun", "src/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write('{"name": "test", "value": 123}');
    proc.stdin.end();

    const exitCode = await proc.exited;
    const stdout = await new Response(proc.stdout).text();

    expect(exitCode).toBe(0);
    expect(stdout.trim()).toBe("Valid JSON");
  });

  test("accepts valid JSON array", async () => {
    const proc = spawn({
      cmd: ["bun", "src/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write('[1, 2, 3, "test"]');
    proc.stdin.end();

    const exitCode = await proc.exited;
    const stdout = await new Response(proc.stdout).text();

    expect(exitCode).toBe(0);
    expect(stdout.trim()).toBe("Valid JSON");
  });

  test("rejects invalid JSON", async () => {
    const proc = spawn({
      cmd: ["bun", "src/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write('{"invalid": json}');
    proc.stdin.end();

    const exitCode = await proc.exited;
    const stderr = await new Response(proc.stderr).text();

    expect(exitCode).toBe(1);
    expect(stderr).toContain("Error: Invalid JSON");
  });

  test("rejects empty input", async () => {
    const proc = spawn({
      cmd: ["bun", "src/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write("");
    proc.stdin.end();

    const exitCode = await proc.exited;
    const stderr = await new Response(proc.stderr).text();

    expect(exitCode).toBe(1);
    expect(stderr).toContain("Error: Empty input");
  });

  test("handles whitespace-only input", async () => {
    const proc = spawn({
      cmd: ["bun", "src/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write("   \n  \t  ");
    proc.stdin.end();

    const exitCode = await proc.exited;
    const stderr = await new Response(proc.stderr).text();

    expect(exitCode).toBe(1);
    expect(stderr).toContain("Error: Empty input");
  });
});

