#!/usr/bin/env bun

/**
 * Fast JSON validation utility leveraging Bun's native JSON parsing.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
  line?: number;
  column?: number;
}

/**
 * Validates a JSON string using Bun's native JSON.parse with try-catch error handling.
 */
export function validateJson(input: string): ValidationResult {
  if (input.trim() === '') {
    return {
      valid: false,
      error: 'Input is empty'
    };
  }

  try {
    JSON.parse(input);
    return { valid: true };
  } catch (error) {
    if (error instanceof SyntaxError) {
      const match = error.message.match(/position (\d+)/);
      const position = match ? parseInt(match[1], 10) : undefined;

      if (position !== undefined) {
        const lines = input.substring(0, position).split('\n');
        const line = lines.length;
        const column = lines[lines.length - 1].length + 1;

        return {
          valid: false,
          error: error.message,
          line,
          column
        };
      }

      return {
        valid: false,
        error: error.message
      };
    }

    return {
      valid: false,
      error: error instanceof Error ? error.message : 'Unknown error'
    };
  }
}

/**
 * CLI entry point for JSON validation.
 */
async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    const stdin = await Bun.stdin.text();
    const result = validateJson(stdin);
    printResult(result);
    process.exit(result.valid ? 0 : 1);
  }

  for (const filePath of args) {
    try {
      const file = Bun.file(filePath);
      const content = await file.text();
      const result = validateJson(content);

      console.log(`File: ${filePath}`);
      printResult(result);

      if (!result.valid) {
        process.exit(1);
      }
    } catch (error) {
      console.error(`Error reading file ${filePath}:`, error instanceof Error ? error.message : 'Unknown error');
      process.exit(1);
    }
  }

  process.exit(0);
}

function printResult(result: ValidationResult): void {
  if (result.valid) {
    console.log('✓ Valid JSON');
  } else {
    console.error('✗ Invalid JSON');
    if (result.error) {
      console.error(`  Error: ${result.error}`);
    }
    if (result.line !== undefined && result.column !== undefined) {
      console.error(`  Location: line ${result.line}, column ${result.column}`);
    }
  }
}

if (import.meta.main) {
  main();
}

import { describe, test, expect } from 'bun:test';
import { validateJson, type ValidationResult } from './validate-json';

describe('validateJson', () => {
  describe('valid JSON', () => {
    test('validates simple object', () => {
      const result = validateJson('{"key": "value"}');
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test('validates simple array', () => {
      const result = validateJson('[1, 2, 3]');
      expect(result.valid).toBe(true);
    });

    test('validates nested structures', () => {
      const result = validateJson('{"nested": {"array": [1, 2, {"deep": true}]}}');
      expect(result.valid).toBe(true);
    });

    test('validates null', () => {
      const result = validateJson('null');
      expect(result.valid).toBe(true);
    });

    test('validates boolean', () => {
      const result = validateJson('true');
      expect(result.valid).toBe(true);
    });

    test('validates number', () => {
      const result = validateJson('42');
      expect(result.valid).toBe(true);
    });

    test('validates string', () => {
      const result = validateJson('"hello"');
      expect(result.valid).toBe(true);
    });

    test('validates JSON with whitespace', () => {
      const result = validateJson(`
        {
          "key": "value",
          "number": 123
        }
      `);
      expect(result.valid).toBe(true);
    });
  });

  describe('invalid JSON', () => {
    test('rejects malformed object', () => {
      const result = validateJson('{key: "value"}');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test('rejects trailing comma', () => {
      const result = validateJson('{"key": "value",}');
      expect(result.valid).toBe(false);
    });

    test('rejects unclosed object', () => {
      const result = validateJson('{"key": "value"');
      expect(result.valid).toBe(false);
    });

    test('rejects unclosed array', () => {
      const result = validateJson('[1, 2, 3');
      expect(result.valid).toBe(false);
    });

    test('rejects single quote strings', () => {
      const result = validateJson("{'key': 'value'}");
      expect(result.valid).toBe(false);
    });

    test('provides line and column for syntax errors', () => {
      const result = validateJson(`{
  "valid": "field",
  "invalid": true,
}`);
      expect(result.valid).toBe(false);
      expect(result.line).toBeDefined();
      expect(result.column).toBeDefined();
    });
  });

  describe('edge cases', () => {
    test('rejects empty string', () => {
      const result = validateJson('');
      expect(result.valid).toBe(false);
      expect(result.error).toBe('Input is empty');
    });

    test('rejects whitespace-only string', () => {
      const result = validateJson('   \n  \t  ');
      expect(result.valid).toBe(false);
      expect(result.error).toBe('Input is empty');
    });

    test('validates empty object', () => {
      const result = validateJson('{}');
      expect(result.valid).toBe(true);
    });

    test('validates empty array', () => {
      const result = validateJson('[]');
      expect(result.valid).toBe(true);
    });

    test('handles unicode characters', () => {
      const result = validateJson('{"emoji": "🚀", "chinese": "你好"}');
      expect(result.valid).toBe(true);
    });

    test('validates escaped characters', () => {
      const result = validateJson('{"escaped": "line1\\nline2\\ttab"}');
      expect(result.valid).toBe(true);
    });
  });

  describe('performance', () => {
    test('handles small JSON quickly', () => {
      const input = JSON.stringify({ key: 'value' });
      const start = performance.now();

      for (let i = 0; i < 1000; i++) {
        validateJson(input);
      }

      const duration = performance.now() - start;
      expect(duration).toBeLessThan(100);
    });

    test('handles medium JSON efficiently', () => {
      const obj = {
        users: Array.from({ length: 100 }, (_, i) => ({
          id: i,
          name: `User ${i}`,
          email: `user${i}@example.com`,
          active: i % 2 === 0
        }))
      };
      const input = JSON.stringify(obj);

      const start = performance.now();
      const result = validateJson(input);
      const duration = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(duration).toBeLessThan(10);
    });

    test('handles large JSON structures', () => {
      const largeArray = Array.from({ length: 10000 }, (_, i) => ({
        index: i,
        value: Math.random(),
        nested: { data: `item-${i}` }
      }));
      const input = JSON.stringify(largeArray);

      const start = performance.now();
      const result = validateJson(input);
      const duration = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(duration).toBeLessThan(100);
    });
  });
});

